INSERT INTO grammar.content_catalog_topics(version,slug,catalog_hash,payload)
SELECT 'core-2026-09-v4','past-continuous','87b630c771d79eac83e3be02f06e226cf9455e201ca4d4e9ebd574542396373d',payload || '{"slug":"past-continuous","title":"Past continuous and past simple","level":"A2","order":27,"summary":"Describe an activity in progress when another past event happened.","learningGoals":["A past activity in progress","Negatives and questions","A background and an event"],"guidance":"Read the rules and examples, then try a 20-question session. Explain why your chosen form fits the context and revisit any missed skill.","rules":[{"title":"A past activity in progress","explanation":"Use was or were plus an -ing form for a background activity already happening at a past moment. I, he, she and it take was; you, we and they take were.","examples":["I was sketching the view.","They were preparing breakfast."]},{"title":"Negatives and questions","explanation":"Put not after was or were. Move was or were before the subject to ask a question. Keep the -ing form.","examples":["We were not skating.","Was the dog barking?"]},{"title":"A background and an event","explanation":"The past continuous can show an activity that began before a past-simple event. The event happens during that activity; the sentence need not tell us when the activity ended.","examples":["I was sketching when the rain began.","The rain began during the sketching."]}],"tips":["Check both the meaning and the form before answering.","Use the explanation to understand a mistake before moving on.","A practice result is feedback, not an official language certificate."],"source":"seed","provenance":{"version":"foundations-2026-09-v2","authorship":"Grammacho; generated offline with AI assistance","kind":"original-guidance-aligned","reviewStatus":"automated-checked; educator-review-pending","referenceIds":["bc-past-continuous"],"assessment":"Practice only; approximate teaching labels, not validated CEFR assessment."},"chapter":{"introduction":["The past continuous presents an activity as in progress at a past reference point. It often creates the background to a story. A later event in past simple may interrupt or occur during that activity. This is a viewpoint distinction: it does not require the activity to be long in absolute time."],"rules":[{"title":"A past activity in progress","explanation":"Use was or were plus an -ing form for a background activity already happening at a past moment. I, he, she and it take was; you, we and they take were.","examples":["I was sketching the view.","They were preparing breakfast.","She **was reading** when the lights **went out**."],"pattern":"I / she **was working** · we / they **were working**","paragraphs":["Was goes with I, he, she, it and a singular noun; were goes with you and plural subjects. Keep the -ing form unchanged. At eight, I was studying places the listener inside the activity at eight rather than presenting it as a whole completed event."],"id":"past-continuous-foundation-1","domain":"verbs","referenceIds":["bc-past-continuous"],"readingVersion":"foundations-2026-09-v2"},{"title":"Negatives and questions","explanation":"Put not after was or were. Move was or were before the subject to ask a question. Keep the -ing form.","examples":["We were not skating.","Was the dog barking?","While I **was cooking**, he **was washing** up."],"pattern":"**Was** she **working**? / She **was not working**.","paragraphs":["Move was/were before the subject in questions, and put not after it in negatives. Do not use did with a past-continuous verb phrase. Was she working? is different from Did she work?, both in structure and in viewpoint."],"id":"past-continuous-foundation-2","domain":"verbs","referenceIds":["bc-past-continuous"],"readingVersion":"foundations-2026-09-v2"},{"title":"A background and an event","explanation":"The past continuous can show an activity that began before a past-simple event. The event happens during that activity; the sentence need not tell us when the activity ended.","examples":["I was sketching when the rain began.","The rain began during the sketching.","**Were** they **waiting** when you arrived?"],"pattern":"We **were eating** when the phone **rang**.","paragraphs":["When and while help relate events, but they are not mechanical tense triggers. While often introduces a continuing activity; when can introduce a shorter event or identify a time. Two simultaneous background activities can both use past continuous."],"id":"past-continuous-foundation-3","domain":"verbs","referenceIds":["bc-past-continuous"],"readingVersion":"foundations-2026-09-v2"},{"title":"Contrasts and edge cases","explanation":"A state such as knew normally stays simple, even when it held at the background time. Past continuous can also show a temporary past situation or a repeated annoying activity with always. To show an activity continuing up to an earlier past point, study past perfect continuous.","examples":["She **was reading** when the lights **went out**.","While I **was cooking**, he **was washing** up.","**Were** they **waiting** when you arrived?"],"id":"past-continuous-foundation-4","domain":"verbs","referenceIds":["bc-past-continuous"],"readingVersion":"foundations-2026-09-v2"}],"recap":["I / she **was working** · we / they **were working**","**Was** she **working**? / She **was not working**.","We **were eating** when the phone **rang**."],"readingVersion":"core-2026-09-v4"},"stage":"3 · Time and experience","prerequisites":["past-simple"],"readingReferenceIds":["bc-past-continuous"]}'::jsonb FROM grammar.content_catalog_topics WHERE version='core-2026-09-v3' AND slug='past-continuous'
